24: /**
25:  * Khoá cho một thao tác. Gọi bao nhiêu lần cũng trả về CÙNG một chuỗi, cho tới
26:  * khi `xongThaoTac(dinhDanh)` được gọi.
27:  *
28:  * `dinhDanh` phải mô tả THAO TÁC, không phải lần bấm: gồm khách nào, việc gì,
29:  * trạng thái nào. Hai thao tác khác nhau phải ra hai định danh khác nhau, nếu
30:  * không thao tác thứ hai sẽ bị nuốt mất vì trùng khoá với thao tác thứ nhất.
31:  */
32: export function khoaThaoTac(dinhDanh: string): string {
33:   const co = dangMo.get(dinhDanh);
34:   if (co) return co;
35:   const moi =
36:     typeof crypto !== "undefined" && "randomUUID" in crypto
37:       ? crypto.randomUUID()
38:       : // Trình duyệt cũ hoặc ngữ cảnh không an toàn (http). Phòng khám chạy
39:         // trên http nội bộ, nên nhánh này KHÔNG phải lý thuyết.
40:         `k-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
41:   dangMo.set(dinhDanh, moi);
42:   return moi;
43: }

