60: async function khoaChoGuiLai(
61:   thaoTac: string,
62:   duLieu: Record<string, unknown>,
63: ): Promise<{ khoa: string; khoaLuu: string; khoaTrongTab: string }> {
64:   const raw = JSON.stringify(chuanHoa(duLieu));
65:   let hashNhanh = 2166136261;
66:   for (let i = 0; i < raw.length; i++) {
67:     hashNhanh = Math.imul(hashNhanh ^ raw.charCodeAt(i), 16777619);
68:   }
69:   const goc = `${thaoTac}:${(hashNhanh >>> 0).toString(16)}:${raw.length}`;
70:   let khoaTrongTab = goc;
71:   let hauTo = 0;
72:   while (dangTaoKhoa.has(khoaTrongTab) && dangTaoKhoa.get(khoaTrongTab)?.raw !== raw) {
73:     khoaTrongTab = `${goc}:${++hauTo}`;
74:   }
75:   const truoc = dangTaoKhoa.get(khoaTrongTab);
76:   if (truoc?.raw === raw) return truoc.promise;
77: 
78:   const promise = (async () => {
79:     const khoaLuu = `${KHOA_CHO_GUI}${thaoTac}:${await bamPayload(duLieu)}`;
80:     try {
81:       const daLuu = window.sessionStorage.getItem(khoaLuu);
82:       if (daLuu) return { khoa: daLuu, khoaLuu, khoaTrongTab };
83:       const khoa = idNgauNhien();
84:       window.sessionStorage.setItem(khoaLuu, khoa);
85:       return { khoa, khoaLuu, khoaTrongTab };
86:     } catch {
87:       throw new Error(LOI_KHONG_LUU_DUOC_KHOA);
88:     }
89:   })();
90:   dangTaoKhoa.set(khoaTrongTab, { raw, promise, dangGui: 0, coLoi: false });
91:   try {
92:     return await promise;
93:   } catch (error) {
94:     dangTaoKhoa.delete(khoaTrongTab);
95:     throw error;
96:   }
97: }

