175: /** Số phút từ `tu` tới `den` (thời điểm ISO hoặc ms). Rác / thiếu → null; không bao giờ âm. */
176: export function phut(tu: string | null | undefined, den: string | number | null | undefined): number | null {
177:   const a = ms(tu);
178:   const b = typeof den === "number" ? (Number.isFinite(den) ? den : null) : ms(den);
179:   if (a == null || b == null) return null;
180:   return Math.max(0, Math.floor((b - a) / 60_000));
181: }

