110: export function doanNoi(moc: MocMayChu[], bayGio: number): Doan[] {
111:   const cuoi = moc.reduce((k, m, i) => (m.bat != null ? i : k), -1);
112:   return moc.slice(0, -1).map((m, i) => {
113:     const sau = moc[i + 1];
114:     if (m.hom_truoc) return { nhan: "hôm trước", trangThai: "xong" };
115:     if (m.bat != null && sau.bat != null) {
116:       const tu = m.ket ?? m.bat;
117:       const p = phutGiua(tu, new Date(sau.bat).getTime());
118:       return { nhan: p >= 1 ? khoang(p) : null, trangThai: "xong" };
119:     }
120:     if (i === cuoi && m.trang_thai !== "chua") {
121:       const tu = m.ket ?? m.bat!;
122:       const p = phutGiua(tu, bayGio);
123:       if (p < 1) return { nhan: "vừa xong", trangThai: "dang" };
124:       return {
125:         nhan: m.ket ? `chờ ${khoang(p)}` : `đang ${khoang(p)}`,
126:         trangThai: "dang",
127:       };
128:     }
129:     return { nhan: null, trangThai: m.trang_thai === "xong" ? "xong" : "chua" };
130:   });
131: }

152: export function phutDichVu(d: DichVuHanhTrinh, bayGio: number): PhutDichVu {
153:   const cacMoc: [string, string | null][] = [
154:     ["Gửi", d.gui],
155:     ["Thu", d.thu],
156:     ["Bắt đầu", d.bat_dau],
157:     ["Xong", d.xong],
158:   ];
159:   const moc = cacMoc
160:     .flatMap(([a, v]) => (v ? [`${a} ${fmtTime(v)}`] : []))
161:     .join(" · ");
162:   if (d.trang_thai === "BO") return { moc, cho: null, lam: null, tong: null, dangChay: false };
163:   const ms = (v: string) => new Date(v).getTime();
164:   const phut = (a: number, b: number) => Math.max(0, Math.floor((b - a) / 60_000));
165:   const xong = d.xong ? ms(d.xong) : null;
166:   const cuoi = xong ?? bayGio;
167:   const tuCho = ms(d.thu ?? d.gui);
168:   const batDau = d.bat_dau ? ms(d.bat_dau) : null;
169:   const cho = batDau != null ? phut(tuCho, batDau) : xong == null ? phut(tuCho, bayGio) : null;
170:   const lam = batDau != null ? phut(batDau, cuoi) : null;
171:   return { moc, cho, lam, tong: phut(ms(d.gui), cuoi), dangChay: xong == null };

