28: function partsToIso(d: string, mo: string, y: string): string {
29:   if (!d || !mo || y.length !== 4) return "";
30:   const dd = Number(d);
31:   const mm = Number(mo);
32:   const yy = Number(y);
33:   if (!Number.isInteger(dd) || !Number.isInteger(mm) || !Number.isInteger(yy))
34:     return "";
35:   if (mm < 1 || mm > 12) return "";
36:   if (dd < 1 || dd > daysInMonth(mm, yy)) return "";
37:   return `${String(yy).padStart(4, "0")}-${String(mm).padStart(2, "0")}-${String(dd).padStart(2, "0")}`;
38: }

