45: export function useNgheBang(
46:   bang: readonly string[],
47:   khiDoi: () => void | Promise<unknown>,
48: ): void {
49:   // Qua ref: `khiDoi` thường là hàm khai trong thân component, mỗi lượt render
50:   // một bản mới. Đưa thẳng vào deps là gỡ/gắn lại tay nghe ở mỗi lượt render.
51:   const khiDoiRef = useRef(khiDoi);
52:   useEffect(() => {
53:     khiDoiRef.current = khiDoi;
54:   }, [khiDoi]);
55: 
56:   // Khoá bằng chuỗi: mảng khai tại chỗ là một mảng mới mỗi lượt render.
57:   const khoa = bang.join(",");
58: 
59:   useEffect(() => {
60:     const can = new Set(khoa.split(","));
61:     const motLuot = taoMotLuot();
62:     const nhip = taoNhipLamMoi({
63:       lamMoi: () => {
64:         motLuot(async () => {
65:           await khiDoiRef.current();
66:         }).catch((loi) => console.error("[nghe-bang] lượt tải lại lỗi:", loi));
67:       },
68:       dangAn: () => document.visibilityState === "hidden",
69:       hen: (fn, ms) => setTimeout(fn, ms),
70:       huy: (h) => clearTimeout(h as ReturnType<typeof setTimeout>),
71:       ...NHIP_NGHE_TIN,
72:     });
73:     const nghe = (ev: Event) => {
74:       const t = (ev as CustomEvent<string | null>).detail;
75:       if (t === null || can.has(t)) nhip.nhan();
76:     };
77:     window.addEventListener(SU_KIEN_BANG, nghe);
78:     return () => {
79:       window.removeEventListener(SU_KIEN_BANG, nghe);
80:       nhip.dung();
81:     };
82:   }, [khoa]);
83: }

