42: // hard-code theo schema). Chỉ áp cho radio/checkbox_group có option khớp.
43: const NORMAL_LABELS = new Set(["bình thường", "bt", "không", "ko"]);
44: function normalOption(field: FormField): string | null {
45:   const opt = (field.options ?? []).find(
46:     (o) =>
47:       NORMAL_LABELS.has(o.label.trim().toLowerCase()) ||
48:       NORMAL_LABELS.has(o.value.trim().toLowerCase()),
49:   );
