347: export interface KhoTrangThai<T> {
348:   doc: () => T;
349:   dat: (moi: T) => void;
350:   /** Đăng ký nghe đổi. Trả hàm thôi nghe — đúng hình `useSyncExternalStore`. */
351:   nghe: (fn: () => void) => Go;
