354: /** Một ô giá trị có người nghe. Tách thành hàm để test không đụng bản dùng chung. */
355: export function taoKhoTrangThai<T>(dau: T): KhoTrangThai<T> {
356:   let hienTai = dau;
357:   const nguoiNghe = new Set<() => void>();
358:   return {
359:     doc: () => hienTai,
360:     dat(moi) {
361:       // Không đổi thì không báo — mỗi lời báo là một lượt render ở người nghe.
362:       if (Object.is(moi, hienTai)) return;
363:       hienTai = moi;
364:       for (const fn of [...nguoiNghe]) fn();
365:     },
366:     nghe(fn) {
367:       nguoiNghe.add(fn);
368:       return () => {
369:         nguoiNghe.delete(fn);
370:       };
371:     },
372:   };
373: }
