28: function cacBang(container: HTMLElement): { tieuDe: string[]; dong: string[][] }[] {
29:   const bang: { tieuDe: string[]; dong: string[][] }[] = [];
30:   const nguonRieng = container.querySelectorAll("table[data-excel-source]");
31:   for (const table of Array.from(nguonRieng.length ? nguonRieng : container.querySelectorAll("table"))) {
32:     const header = Array.from(table.querySelectorAll("thead tr")).at(-1);
33:     if (!header) continue;
34:     const tieuDe = Array.from(header.querySelectorAll("th:not([data-excel-ignore]), td:not([data-excel-ignore])")).map(noiDungO);
35:     if (!tieuDe.some(Boolean)) continue;
36:     const dong = Array.from(table.querySelectorAll("tbody tr"))
37:       .filter((tr) => !tr.hasAttribute("data-excel-ignore") && getComputedStyle(tr).display !== "none")
38:       .map((tr) => Array.from(tr.querySelectorAll(":scope > td:not([data-excel-ignore]), :scope > th:not([data-excel-ignore])"), noiDungO))
39:       .filter((cells) => cells.some(Boolean));
40:     bang.push({ tieuDe: tieuDe.map((x, i) => x || `Cột ${i + 1}`), dong });
41:   }
42:   for (const list of Array.from(nguonRieng.length ? [] : container.querySelectorAll("ul.rounded-card, ul.space-y-3"))) {
43:     const items = Array.from(list.querySelectorAll(":scope > li")).map(noiDungO).filter(Boolean);
44:     if (items.length) bang.push({ tieuDe: ["Nội dung"], dong: items.map((item) => [item]) });
45:   }
46:   return bang;
47: }

